function face(o){
  if(o.photo) return `<img class="face" src="${o.photo}" alt="${o.t}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=function(){this.onerror=null;this.src='${FB}'};this.src='assets/people/${o.jpg||''}'">`.replace("assets/people/", "assets/people/").replace("src='assets/people/'", "src='"+FB+"'");
  return `<img class="face" src="${FB}" alt="${o.t}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='${FB}'">`;
}
function finItem(key, day, tags, intro, ach, hi){
  const o = F[key];
  return {
    title: o.t,
    tag: `第${day}天 · 名人故事`,
    blocks: [
      {h:"📷 人物照片", body: face(o)},
      {h:"🏷 人物标签", body:`<p class="tags">${tags}</p>`},
      {h:"📖 人物介绍（在世）", body:`<p>${intro}</p>`},
      {h:"🏆 主要成就", body:`<p>${ach}</p>`},
      {h:"🌟 一句话亮点", body:`<p>${hi}</p>`}
    ]
  };
}
