/* ---------------- geo（出海品牌 · GEO 切入点专题，14 天 × 6 家） ---------------- */
function gco(name, tier, sketch, biz, play, found, turn, geo, look, site){
  const t = tier==='hd' ? '头部' : '腰部';
  return `<div class="co"><div class="co-h"><b>${name}</b><span class="co-t ${tier}">${t}</span></div>`
    + `<div class="co-r"><b>速写：</b>${sketch}</div>`
    + `<div class="co-r"><b>主营业务：</b>${biz}</div>`
    + `<div class="co-r"><b>市场与打法：</b>${play}</div>`
    + `<div class="co-r found"><b>📜 发家史：</b>${found}</div>`
    + `<div class="co-r turn"><b>🔑 转折点：</b>${turn}</div>`
    + `<div class="co-r geo"><b>🎯 GEO 切入点：</b>${geo}</div>`
    + `<div class="co-r look"><b>💡 看点：</b>${look}</div>`
    + `<div class="co-r">官网：<a class="co-site" href="${site}" target="_blank" rel="noopener">🌐 ${site}</a></div></div>`;
}
